# Original stylised modern MINI Cooper 3-door hatch (F56 look) for a Three.js city.
# Run: blender -b --factory-startup -P build_mini.py -- out.glb
# Blender axes: nose +X, up +Z, right side = -Y  (glTF export_yup -> three.js: forward +X, up +Y, right +Z).
# Origin on ground, centred lengthwise and widthwise.  Side profile is driven by the traced silhouette of
# miniref/right.png (px tables below), scaled to length 3.82 m.  Everything per-side (glass, trim, flares,
# handles) is generated by ONE side_layout(side) called for side=+1 (right, -Y) and side=-1 (left, +Y).
import bpy, bmesh, math, sys
from mathutils import Vector

# ================= profile / layout constants =================
LEN = 3.82
PXM, ZS, CXP, GRD = LEN / 1207.0, 0.88, 628.5, 885.0   # m/px (x), vertical squash vs the (tall) ref, centre px, ground px
cx = lambda p: (p - CXP) * PXM
cz = lambda p: (GRD - p) * PXM * ZS
W = 0.865                      # max half width of body (width 1.73)
ZB = 0.17                      # sill / underside height
BELT = 0.96                    # beltline (top of body under the glasshouse)
TUMBLE = 0.12                  # wall tumblehome between z=0.45 and z=0.85
WR, WY, RA, RF = 0.32, 0.70, 0.37, 0.075   # wheel radius, wheel y, arch opening radius, flare width
WHEEL_XF, WHEEL_XR = 1.17, -1.36          # wheel centres (wheelbase 2.53, overhang 0.74 / 0.55)
INSET = 0.28                   # arch cavity depth
XFS, LF, NF = 1.29, 0.62, 2.4  # plan: front arc start / length / superellipse exponent
XRS, LR, NR = -1.45, 0.46, 3.4
# top-centre silhouette (px read from right.png): rear deck, belt, hood + nose
TAIL_PX = [(24, 730), (28, 668), (44, 654), (50, 610), (56, 580), (64, 553), (76, 537), (92, 525)]
HOOD_PX = [(948, 536), (990, 542), (1020, 545), (1060, 553), (1100, 565), (1140, 584), (1172, 602), (1196, 620), (1212, 640), (1224, 672), (1230, 720), (1232, 760)]
ROOF_PX = [(155, 425), (190, 397), (230, 389), (270, 383), (310, 376), (350, 373), (430, 369), (470, 368), (550, 368), (630, 371), (710, 380), (750, 391), (775, 402), (795, 425)]
# glasshouse (black pillar band) -- linear in z between belt and roof underside
GH_Z = [0.955, 1.03, 1.32, 1.335]
gh_hw = lambda z: 0.65 - (z - 0.96) * 0.35
gh_xf = lambda z: 1.00 - (z - 0.96) * 1.395     # windscreen plane (rake ~54 deg)
gh_xr = lambda z: -1.68 + (z - 0.96) * 0.725    # rear screen plane (rake ~36 deg)
GH_RC = 0.09
GLASS_Z = (1.03, 1.32); DOOR_X0, QUART_X1 = -0.50, -0.72
DOOR_CUTS = (-0.63, 0.72)
ROOF_HW, ROOF_CROWN, ROOF_T = 0.532, 0.03, 0.055
COL = dict(CarBody='#efe7d6', CarRoof='#c9252b', CarGlass='#7e939f', CarTrim='#17191c', CarChrome='#aeb4ba', CarHeadlight='#fff6e0', CarTaillight='#c01414', CarInterior='#2b2724', CarPlate='#f3f1ea', CarRim='#4a4e54')

# ================= helpers =================
bpy.ops.wm.read_factory_settings(use_empty=True)
def lin(h):
    c = [int(h[i:i + 2], 16) / 255 for i in (1, 3, 5)]
    return tuple(((x + 0.055) / 1.055) ** 2.4 if x > 0.04045 else x / 12.92 for x in c)
def mat(name, rough=0.4, metal=0.0, alpha=1.0, emit=0.0):
    m = bpy.data.materials.new(name); m.use_nodes = True; b = m.node_tree.nodes['Principled BSDF']
    b.inputs['Base Color'].default_value = (*lin(COL[name]), 1); b.inputs['Roughness'].default_value = rough; b.inputs['Metallic'].default_value = metal
    if alpha < 1:
        b.inputs['Alpha'].default_value = alpha
        try: m.surface_render_method = 'BLENDED'
        except Exception: pass
    if emit: b.inputs['Emission Color'].default_value = (*lin(COL[name]), 1); b.inputs['Emission Strength'].default_value = emit
    return m
M_BODY, M_ROOF, M_GLASS = mat('CarBody', 0.35), mat('CarRoof', 0.3), mat('CarGlass', 0.05, 0.0, 0.55)
M_TRIM, M_CHROME = mat('CarTrim', 0.45), mat('CarChrome', 0.2, 0.7)
M_HEAD, M_TAIL = mat('CarHeadlight', 0.2, 0, 1, 0.8), mat('CarTaillight', 0.3, 0, 1, 0.6)
M_INT, M_PLATE, M_RIM = mat('CarInterior', 0.85), mat('CarPlate', 0.5), mat('CarRim', 0.35, 0.6)
B_BODY, B_TRIM, B_CHR, B_ROOF, B_INT, B_PLATE = 0, 1, 2, 3, 4, 5          # Body mesh slots

def interp(tab, x):
    if x <= tab[0][0]: return tab[0][1]
    for (xa, a), (xb, b) in zip(tab, tab[1:]):
        if x <= xb: return a + (b - a) * (x - xa) / (xb - xa)
    return tab[-1][1]
TAIL = [(cx(p), cz(q)) for p, q in TAIL_PX]
ST_TAB = [(x, min(z, BELT)) for x, z in TAIL] + [(-1.62, BELT), (0.95, BELT)] + [(cx(p), cz(q)) for p, q in HOOD_PX]
NOSE = [(cx(p), cz(q)) for p, q in HOOD_PX if p >= 1100]
ROOF = [(-1.52, 1.365), (-1.46, 1.372)] + [(cx(p), cz(q)) for p, q in ROOF_PX if 190 <= p <= 750] + [(0.40, 1.375), (0.49, 1.36)]   # flat-ended: slab never dips onto the screens
ST = lambda x: interp(ST_TAB, x)
D_TAB = [(-1.91, 0.14), (-1.65, 0.14), (-1.50, 0.06), (0.95, 0.06), (1.25, 0.14), (1.91, 0.16)]
def xtop_f(z):                                         # x where the nose top silhouette passes height z (no limit above/below the nose)
    zs = [n[1] for n in NOSE]
    if z >= zs[0] or z <= zs[-1]: return 9.0
    return interp([(n[1], n[0]) for n in reversed(NOSE)], z)
def xtop_r(z):
    zs = [t[1] for t in TAIL]
    if z <= zs[0]: return -9.0
    return interp([(t[1], t[0]) for t in TAIL if t[1] <= BELT], min(z, 0.99))
def wall_w(z, Wp):                                     # half width of the body wall at height z for plan half width Wp
    s = min(1.0, max(0.0, (z - 0.45) / 0.40)); r = max(0.0, (0.30 - z) / 0.13)
    return Wp * (1 - (TUMBLE * s * s + 0.045 * r * r) / W)
def plan_w(x0):
    if x0 > XFS: return W * max(0.0, 1 - ((x0 - XFS) / LF) ** NF) ** (1 / NF)
    if x0 < XRS: return W * max(0.0, 1 - ((XRS - x0) / LR) ** NR) ** (1 / NR)
    return W
def surf(y, z, off, front):                            # point on the nose (front) / tail (rear) surface at lateral y, height z
    f = min(0.995, abs(y) / (W * wall_w(z, W) / W)); n = NF if front else NR; u = (1 - f ** n) ** (1 / n)
    return Vector((min(XFS + LF * u, xtop_f(z)) + off, y, z)) if front else Vector((max(XRS - LR * u, xtop_r(z)) - off, y, z))
FRONT = lambda y, z, off: surf(y, z, off, True)
REAR = lambda y, z, off: surf(y, z, off, False)

def addf(bm, vs, mi, ref=Vector((0, 0, 0.4)), sign=1):  # face whose normal points away from ref (callable(center)->point), flipped by sign
    try: f = bm.faces.new(vs)
    except ValueError: return None
    f.normal_update(); c = f.calc_center_median(); r = ref(c) if callable(ref) else ref
    if f.normal.dot(c - r) * sign < 0: f.normal_flip()
    f.material_index = mi; return f
def grid(bm, rows, mi, ref=Vector((0, 0, 0.4)), sign=1):   # rows: list of equal-length vertex-position lists
    vr = [[bm.verts.new(p) for p in r] for r in rows]
    for a, b in zip(vr, vr[1:]):
        for i in range(len(a) - 1): addf(bm, (a[i], a[i + 1], b[i + 1], b[i]), mi, ref, sign)
def region(bm, pt, yc, z0, z1, h, ny, nz, off, mi, ref=Vector((0, 0, 0.4))):   # surface-conforming decal: half width h(z) about yc; off may be f(i,k)
    rows = []
    for k in range(nz + 1):
        z = z0 + (z1 - z0) * k / nz; hh = max(0.004, h(z)); rows.append([pt(yc - hh + 2 * hh * i / ny, z, off(i, k) if callable(off) else off) for i in range(ny + 1)])
    grid(bm, rows, mi, ref)
def disc(bm, c, n, r, mi, dome=0.0, seg=14, ref=None):  # fan disc facing n
    u = (Vector((0, 0, 1)) - n * n.z).normalized(); v = n.cross(u); ctr = bm.verts.new(c + n * dome); ring = [bm.verts.new(c + (v * math.cos(2 * math.pi * k / seg) + u * math.sin(2 * math.pi * k / seg)) * r) for k in range(seg)]
    for k in range(seg): addf(bm, (ctr, ring[k], ring[(k + 1) % seg]), mi, c - n)
def tube(bm, c, n, r, length, mi, seg=14):             # open cylinder wall from c along n (outward-facing)
    u = (Vector((0, 0, 1)) - n * n.z).normalized(); v = n.cross(u)
    a = [bm.verts.new(c + (v * math.cos(2 * math.pi * k / seg) + u * math.sin(2 * math.pi * k / seg)) * r) for k in range(seg)]
    b = [bm.verts.new(p.co + n * length) for p in a]
    for k in range(seg): addf(bm, (a[k], a[(k + 1) % seg], b[(k + 1) % seg], b[k]), mi, lambda ctr, c=c, n=n: c + n * ((ctr - c).dot(n)))
def ring_disc(bm, c, n, r0, r1, mi, seg=14):           # annulus facing n
    u = (Vector((0, 0, 1)) - n * n.z).normalized(); v = n.cross(u)
    a = [bm.verts.new(c + (v * math.cos(2 * math.pi * k / seg) + u * math.sin(2 * math.pi * k / seg)) * r0) for k in range(seg)]
    b = [bm.verts.new(c + (v * math.cos(2 * math.pi * k / seg) + u * math.sin(2 * math.pi * k / seg)) * r1) for k in range(seg)]
    for k in range(seg): addf(bm, (a[k], a[(k + 1) % seg], b[(k + 1) % seg], b[k]), mi, c - n)
def box(bm, c, s, mi):
    r = bmesh.ops.create_cube(bm, size=1.0); vs = r['verts']
    for v in vs: v.co = Vector((c[0] + v.co.x * s[0], c[1] + v.co.y * s[1], c[2] + v.co.z * s[2]))
    for f in {f for v in vs for f in v.link_faces}: f.material_index = mi
    bmesh.ops.recalc_face_normals(bm, faces=list({f for v in vs for f in v.link_faces}))
def ellipsoid(bm, c, s, mi, us=10, vs_=6):
    r = bmesh.ops.create_uvsphere(bm, u_segments=us, v_segments=vs_, radius=1.0); vs = r['verts']
    for v in vs: v.co = Vector((c[0] + v.co.x * s[0], c[1] + v.co.y * s[1], c[2] + v.co.z * s[2]))
    fs = list({f for v in vs for f in v.link_faces})
    for f in fs: f.material_index = mi
    bmesh.ops.recalc_face_normals(bm, faces=fs)
def torus(bm, c, n, R, r, mi, seg=14, sides=5):
    u = (Vector((0, 0, 1)) - n * n.z).normalized(); v = n.cross(u); rings = []
    for k in range(seg):
        a = 2 * math.pi * k / seg; d = u * math.cos(a) + v * math.sin(a); cc = c + d * R
        rings.append([bm.verts.new(cc + (d * math.cos(b) + n * math.sin(b)) * r) for b in (2 * math.pi * s / sides for s in range(sides))])
    for k in range(seg):
        A, B = rings[k], rings[(k + 1) % seg]
        for s in range(sides): addf(bm, (A[s], A[(s + 1) % sides], B[(s + 1) % sides], B[s]), mi, lambda ctr: c + ((ctr - c) - n * (ctr - c).dot(n)).normalized() * R)
def prism(poly, axis, a0, a1):                          # window cutter: polygon (u,v) extruded along y (poly in x,z) or x (poly in y,z)
    bmc = bmesh.new(); P = (lambda u, v, t: Vector((u, t, v))) if axis == 'y' else (lambda u, v, t: Vector((t, u, v)))
    lo = [bmc.verts.new(P(u, v, a0)) for u, v in poly]; hi = [bmc.verts.new(P(u, v, a1)) for u, v in poly]; n = len(poly)
    for i in range(n): bmc.faces.new((lo[i], lo[(i + 1) % n], hi[(i + 1) % n], hi[i]))
    bmc.faces.new(lo); bmc.faces.new(hi[::-1]); bmesh.ops.recalc_face_normals(bmc, faces=list(bmc.faces))
    return new_obj('cutter', bmc, [])
def new_obj(name, bm, mats):
    me = bpy.data.meshes.new(name); bm.to_mesh(me); bm.free(); ob = bpy.data.objects.new(name, me); bpy.context.collection.objects.link(ob)
    for m in mats: me.materials.append(m)
    return ob

# ================= BODY SHELL (lofted rings along x) =================
T_ROWS = [k / 10 for k in range(11)]
R_TOP = [0.97, 0.92, 0.84, 0.72, 0.55, 0.30, 0.0]
WHEELS = (WHEEL_XF, WHEEL_XR)
def za(x0): return max([WR + math.sqrt(RA ** 2 - (x0 - c) ** 2) for c in WHEELS if abs(x0 - c) < RA] or [-1])
def top_z(x0, y, Wp):                                  # hood/deck surface height at lateral y (matches the ring top points)
    st = ST(x0); zsh = st - interp(D_TAB, x0); wt = wall_w(zsh, Wp); r = min(1.0, y / wt) if wt > 1e-6 else 1.0
    return st + 0.03 * (1 - r * r) - 0.16 * r ** 8 * (interp(D_TAB, x0) / 0.16)
def ring(x0, Wp):
    st = ST(x0); D = interp(D_TAB, x0); zsh = max(st - D, ZB + 0.12); zr = [ZB + (zsh - ZB) * t for t in T_ROWS]; za_ = za(x0)
    if ZB + 0.03 < za_ < zsh - 0.03:                    # snap two wall rows onto the arch contour so the opening is a clean circle
        k = max(i for i, z in enumerate(zr) if z <= za_); k = min(k, len(zr) - 2); zr[k], zr[k + 1] = za_ - 0.003, za_ + 0.003
    half, flags = [(0.0, ZB)], [False]
    for z in zr:
        inset = z < za_; y = wall_w(z, Wp); half.append((max(0.0, y - INSET) if inset else y, z)); flags.append(inset)
    wt = wall_w(zsh, Wp)
    for r in R_TOP:
        half.append((r * wt, st + 0.03 * (1 - r * r) - D * r ** 8)); flags.append(False)
    H = len(half); pts = [(y, z) for y, z in half] + [(-half[k][0], half[k][1]) for k in range(H - 2, 0, -1)]; fl = flags + [flags[k] for k in range(H - 2, 0, -1)]
    return [Vector((x0, -y, z)) for y, z in pts], fl, H
def stations():
    st = []
    for k in range(10): ph = math.pi / 2 * (1 - k / 9); st.append((XRS - LR * math.sin(ph) ** (2 / NR), W * math.cos(ph) ** (2 / NR)))
    mid = {-0.65, -0.2, 0.25, 0.6}
    for c in WHEELS:
        for d in (0, 0.13, 0.25, 0.33, 0.37, 0.41): mid |= {round(c + d, 3), round(c - d, 3)}
    st += [(x, W) for x in sorted(mid) if XRS + 0.01 < x < XFS - 0.01]
    for k in range(12): ph = math.pi / 2 * (1 - k / 11); st.append((XFS + LF * math.sin(ph) ** (2 / NF), W * math.cos(ph) ** (2 / NF)))
    # rear arc was built tip->XRS, mid ascending, front arc built XFS->tip: put front in ascending x order
    return st
ST_ = stations(); ST_.sort(key=lambda s: s[0])
bm = bmesh.new(); R = []; FL = []
for x0, Wp in ST_:
    p, fl, H = ring(x0, Wp); R.append([bm.verts.new(q) for q in p]); FL.append(fl)
N = len(R[0]); shell = []
for i in range(len(R) - 1):
    for j in range(N):
        j2 = (j + 1) % N
        try: f = bm.faces.new((R[i][j], R[i][j2], R[i + 1][j2], R[i + 1][j]))
        except ValueError: continue
        shell.append((f, any(FL[i][a] or FL[i + 1][a] for a in (j, j2))))
bmesh.ops.remove_doubles(bm, verts=list(bm.verts), dist=1e-5)
shell = [(f, t) for f, t in shell if f.is_valid]
# cabin opening in the body top (so the interior is visible through the windows)
cab = [f for f, t in shell if f.is_valid and f.calc_center_median().z > 0.88 and abs(f.calc_center_median().y) < 0.62 and -1.6 < f.calc_center_median().x < 0.96]
bmesh.ops.recalc_face_normals(bm, faces=list(bm.faces))
NONMANIFOLD = sum(1 for e in bm.edges if not e.is_manifold)      # closed shell, measured before the cabin opening is cut
for f, trim in shell:
    if not f.is_valid: continue
    c = f.calc_center_median(); m = B_BODY
    if trim or c.z < 0.215 or (abs(c.y) > 0.5 and c.z < 0.316 and WHEEL_XR + RA - 0.02 < c.x < WHEEL_XF - RA + 0.02): m = B_TRIM
    f.material_index = m
bmesh.ops.delete(bm, geom=[f for f in cab if f.is_valid], context='FACES')
# glasshouse: black pillar band = open shell + boolean window cuts + solidify liner (inner faces = CarInterior)
def gh_ring(z):
    xr, xf, hw, rc = gh_xr(z), gh_xf(z), gh_hw(z), GH_RC; pts = []
    def arc(cxx, cyy, a0, a1):
        for k in range(5): a = math.radians(a0 + (a1 - a0) * k / 4); pts.append(Vector((cxx + rc * math.cos(a), cyy + rc * math.sin(a), z)))
    arc(xf - rc, -(hw - rc), -90, 0); pts.append(Vector((xf, 0, z))); arc(xf - rc, hw - rc, 0, 90); pts.append(Vector(((xr + xf) / 2, hw, z)))
    arc(xr + rc, hw - rc, 90, 180); pts.append(Vector((xr, 0, z))); arc(xr + rc, -(hw - rc), 180, 270); pts.append(Vector(((xr + xf) / 2, -hw, z)))
    return pts
bgh = bmesh.new(); GR = [[bgh.verts.new(p) for p in gh_ring(z)] for z in GH_Z]; NG = len(GR[0])
for a, b in zip(GR, GR[1:]):
    for j in range(NG): bgh.faces.new((a[j], a[(j + 1) % NG], b[(j + 1) % NG], b[j]))
cv = bgh.verts.new(sum((v.co for v in GR[-1]), Vector()) / NG)
for j in range(NG): bgh.faces.new((cv, GR[-1][j], GR[-1][(j + 1) % NG]))
bmesh.ops.recalc_face_normals(bgh, faces=list(bgh.faces))
for f in bgh.faces: f.normal_update()
if sum(f.normal.dot(f.calc_center_median() - Vector((0, 0, f.calc_center_median().z))) for f in bgh.faces if abs(f.normal.z) < 0.5) < 0: bmesh.ops.reverse_faces(bgh, faces=list(bgh.faces))
for f in bgh.faces: f.material_index = B_TRIM
gh_ob = new_obj('GH', bgh, [M_BODY, M_TRIM, M_CHROME, M_ROOF, M_INT])
def apply_mod(ob, m):
    bpy.context.view_layer.objects.active = ob; ob.select_set(True); bpy.ops.object.modifier_apply(modifier=m.name); ob.select_set(False)
MG = 0.012                                              # glass sits MG inside the outer surface; openings are MG smaller than the panes
z0g, z1g = GLASS_Z; X_B = lambda z: gh_xf(z) - GH_RC - 0.12; X_A = lambda z: gh_xr(z) + GH_RC + 0.05
cuts = [prism([(DOOR_X0 + MG, z0g + MG), (X_B(z0g) - MG, z0g + MG), (X_B(z1g) - MG, z1g - MG), (DOOR_X0 + MG, z1g - MG)], 'y', -1.2, 1.2),
        prism([(X_A(z0g) + MG, z0g + MG), (QUART_X1 - MG, z0g + MG), (QUART_X1 - MG, z1g - MG), (X_A(z1g) + MG, z1g - MG)], 'y', -1.2, 1.2)]
zw0, zw1 = 1.0 + MG, 1.32 - MG; hs = lambda z: gh_hw(z) - GH_RC - 0.015 - MG
cuts += [prism([(-hs(zw0), zw0), (hs(zw0), zw0), (hs(zw1), zw1), (-hs(zw1), zw1)], 'x', 0.1, 1.4), prism([(-hs(zw0), zw0), (hs(zw0), zw0), (hs(zw1), zw1), (-hs(zw1), zw1)], 'x', -1.9, -0.9)]
for c_ in cuts:
    m = gh_ob.modifiers.new('cut', 'BOOLEAN'); m.operation = 'DIFFERENCE'; m.solver = 'EXACT'; m.object = c_; apply_mod(gh_ob, m)
m = gh_ob.modifiers.new('wall', 'SOLIDIFY'); m.thickness = 0.03; m.offset = -1.0; m.use_rim = True; m.material_offset = 3; apply_mod(gh_ob, m)
for c_ in cuts: bpy.data.objects.remove(c_)
bm.from_mesh(gh_ob.data); bpy.data.objects.remove(gh_ob)

# ---------------- decals / trim: global (front, rear, hood) ----------------
RAD = lambda c: Vector((0, 0, 0.4))
bg, bl = bmesh.new(), bmesh.new()                       # glass, lights
# hood: twin red stripes from the cowl to the nose lip, scoop with black slot
def hood_pt(x0, y, off): Wp = plan_w(x0); return Vector((x0, -y, top_z(x0, abs(y), Wp) + off))
xs = [1.0, 1.1, 1.2, 1.3, 1.4, 1.5, 1.58, 1.65, 1.72, 1.78, 1.83, 1.86, 1.88, 1.895]
for sg in (1, -1):
    rows = []
    for x0 in xs:
        t = min(1.0, (x0 - 1.0) / 0.75); yc = 0.37 - 0.07 * t; wd = 0.055 - 0.015 * t
        wt = wall_w(ST(x0) - interp(D_TAB, x0), plan_w(x0))
        if yc + wd > wt - 0.01: break
        rows.append([hood_pt(x0, sg * (yc - wd), 0.005), hood_pt(x0, sg * (yc + wd), 0.005)])
    grid(bm, rows, B_ROOF)
def scoop(x0a, x0b, ya, yb, nx, ny, h, mi, off):
    rows = []
    for i in range(nx + 1):
        x0 = x0a + (x0b - x0a) * i / nx; u = i / nx; row = []
        for j in range(ny + 1):
            y = -ya + 2 * ya * j / ny; lat = max(0.0, 1 - (y / ya) ** 2) ** 0.7
            row.append(hood_pt(x0, y, off + h * math.sin(math.pi * u) ** 0.8 * lat))
        rows.append(row)
    grid(bm, rows, mi)
scoop(1.28, 1.64, 0.17, 0.17, 10, 10, 0.042, B_BODY, -0.004)
